import type { SettingDefinition } from "./model.ts";

/** Path of the generated registry module, from the package root. */
export const GENERATED_PATH = "src/settings/registry.generated.ts";

/** The generated TypeScript module holding every setting, for apps that cannot read files. */
export function renderRegistryModule(settings: readonly SettingDefinition[]): string {
  return [
    "// Generated by `pnpm --filter @xos/schemas generate:settings` from packages/schemas/settings/*.yaml.",
    "// Never edit by hand; on a merge conflict, take either side and rerun the generator.",
    'import type { SettingDefinition } from "./model.ts";',
    "",
    `export const SETTINGS: readonly SettingDefinition[] = ${JSON.stringify(settings, null, 2)};`,
    "",
  ].join("\n");
}
